# Guinsaugon Rainfall Window Ledger

Use the local CSX-223 event package to rebuild a rainfall-window threshold ledger for the 17 February 2006 Guinsaugon landslide.

Use the Open-Meteo daily precipitation series as the first daily series and the NASA POWER `PRECTOTCORR` daily series as the second daily series. Set the event day to `2006-02-17`, the prior 14-day window to `2006-02-03` through `2006-02-16`, and the prior 7-day window to `2006-02-10` through `2006-02-16`.

For each daily series, compute prior-14-day precipitation, prior-7-day precipitation, event-day precipitation, and `prior14 / event_day`. Compute the event-day gridded mean precipitation values from ERA5-Land, GPM IMERG, and CHIRPS, then count how many of those three means are at or below `5 mm`.

Use these gates:

- `openmeteo_gate`: prior14 >= `100 mm`, event_day <= `5 mm`, and ratio >= `20`.
- `power_gate`: prior14 >= `300 mm`, event_day <= `10 mm`, and ratio >= `20`.
- `grid_consensus_gate`: at least two gridded event-day means are <= `5 mm`.

Return compact JSON:

```json
{
  "target_family": "guinsaugon_rainfall_window_threshold_ledger",
  "window": {
    "prior14": "YYYY-MM-DD..YYYY-MM-DD",
    "prior7": "YYYY-MM-DD..YYYY-MM-DD",
    "event_day": "YYYY-MM-DD"
  },
  "daily_metrics": {
    "openmeteo": {
      "prior14_mm": 0,
      "prior7_mm": 0,
      "event_day_mm": 0,
      "ratio_prior14_to_event": 0
    },
    "power": {
      "prior14_mm": 0,
      "prior7_mm": 0,
      "event_day_mm": 0,
      "ratio_prior14_to_event": 0
    }
  },
  "grid_means_mm": {
    "era5_land": 0,
    "gpm": 0,
    "chirps": 0,
    "le5_count": 0
  },
  "gates": {
    "openmeteo_gate": true,
    "power_gate": true,
    "grid_consensus_gate": true
  },
  "answer": "<antecedent_wetness_ledger_pass or antecedent_wetness_ledger_fail>",
  "formula_note": "<one short formula note>"
}
```

compute_gt_py:
#!/usr/bin/env python3
from __future__ import annotations

import json
from datetime import date, timedelta
from pathlib import Path
from typing import Any


TASK_ID = "CSX-223_Q2"
EVENT_ID = "CSX-223"
TARGET_FAMILY = "guinsaugon_rainfall_window_threshold_ledger"
TASK_DIR = Path(__file__).resolve().parent
PACKAGE_RELATIVE_PATH = f"event_packages/standard_event_packages/packages/{EVENT_ID}"

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_003_Locked_event_anchor_Southern_Leyte_Guinsaugon_landslide.json",
    "data/physical_hazard/physical_hazard_001_Open-Meteo_daily_weather_fill.json",
    "data/physical_hazard/physical_hazard_002_NASA_POWER_daily_weather_fill.json",
    "data/physical_hazard/physical_hazard_003_ERA5-Land_hourly_aggregate_stats.json",
    "data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "data/physical_hazard/physical_hazard_005_CHIRPS_daily_event_accumulated_precipitation.json",
]

RUBRIC = {
    "total_points": 20,
    "criteria": [
        {
            "name": "answer_schema",
            "points": 3,
            "description": "Returns compact JSON with target_family, window, daily_metrics, grid_means_mm, gates, answer, and formula_note.",
            "partial_credit": "Award 1-2 points for parseable JSON that preserves the final answer and most required groups but has minor field-name or nesting drift.",
        },
        {
            "name": "openmeteo_window_math",
            "points": 4,
            "description": "Computes Open-Meteo prior14 = 143.8 mm, prior7 = 71.6 mm, event_day = 2.0 mm, and ratio = 71.9 within tolerance.",
            "partial_credit": "Award 2-3 points for using the correct date windows with one arithmetic or rounding error; award 1 point for only two correct Open-Meteo values.",
        },
        {
            "name": "power_window_math",
            "points": 4,
            "description": "Computes NASA POWER prior14 = 441.1 mm, prior7 = 296.5 mm, event_day = 4.4 mm, and ratio = 100.9 within tolerance.",
            "partial_credit": "Award 2-3 points for using the correct date windows with one arithmetic or rounding error; award 1 point for only two correct POWER values.",
        },
        {
            "name": "gridded_event_day_check",
            "points": 3,
            "description": "Reports event-day means of 4.64 mm, 2.40 mm, and 0.00 mm, then counts all three as at or below 5 mm.",
            "partial_credit": "Award 1-2 points for two correct gridded means or a correct low-mean count with one source value missing.",
        },
        {
            "name": "threshold_gate_logic",
            "points": 3,
            "description": "Applies the three stated gates correctly and marks openmeteo_gate, power_gate, and grid_consensus_gate true.",
            "partial_credit": "Award 1-2 points for evaluating two gates correctly or for using the right thresholds with one Boolean mistake.",
        },
        {
            "name": "final_label",
            "points": 2,
            "description": "Reports antecedent_wetness_ledger_pass because all three gates pass.",
            "partial_credit": "Award 1 point for a compatible pass conclusion that omits the exact label or the all-gates condition.",
        },
        {
            "name": "bounded_formula_note",
            "points": 1,
            "description": "Keeps the formula note short and limits the interpretation to the computed windows, ratios, gridded means, and gates.",
            "partial_credit": "Award 0.5 points for a mostly bounded note with minor extra prose that does not change the numeric conclusion.",
        },
    ],
}


def repo_root() -> Path:
    return TASK_DIR.parents[2]


def package_root() -> Path:
    return repo_root() / PACKAGE_RELATIVE_PATH


def read_json(rel_path: str) -> Any:
    with (package_root() / rel_path).open("r", encoding="utf-8") as handle:
        return json.load(handle)


def inclusive_dates(start: date, end: date) -> list[date]:
    days = (end - start).days
    return [start + timedelta(days=offset) for offset in range(days + 1)]


def round1(value: float) -> float:
    return round(value + 0.0, 1)


def round2(value: float) -> float:
    return round(value + 0.0, 2)


def openmeteo_series(payload: dict[str, Any]) -> dict[str, float]:
    daily = payload["daily"]
    return {
        day: float(precip)
        for day, precip in zip(daily["time"], daily["precipitation_sum"], strict=True)
    }


def power_series(payload: dict[str, Any]) -> dict[str, float]:
    values = payload["properties"]["parameter"]["PRECTOTCORR"]
    return {
        f"{key[:4]}-{key[4:6]}-{key[6:8]}": float(value)
        for key, value in values.items()
    }


def sum_window(series: dict[str, float], days: list[date]) -> float:
    return sum(series[day.isoformat()] for day in days)


def window_metrics(series: dict[str, float], event_day: date) -> dict[str, float]:
    prior14_days = inclusive_dates(event_day - timedelta(days=14), event_day - timedelta(days=1))
    prior7_days = inclusive_dates(event_day - timedelta(days=7), event_day - timedelta(days=1))
    prior14 = sum_window(series, prior14_days)
    prior7 = sum_window(series, prior7_days)
    event_value = series[event_day.isoformat()]
    ratio = prior14 / event_value
    return {
        "prior14_mm": round1(prior14),
        "prior7_mm": round1(prior7),
        "event_day_mm": round1(event_value),
        "ratio_prior14_to_event": round1(ratio),
    }


def main() -> None:
    event = read_json("metadata/event.json")
    anchor = read_json(
        "data/event_reports/event_reports_003_Locked_event_anchor_Southern_Leyte_Guinsaugon_landslide.json"
    )
    openmeteo = read_json("data/physical_hazard/physical_hazard_001_Open-Meteo_daily_weather_fill.json")
    power = read_json("data/physical_hazard/physical_hazard_002_NASA_POWER_daily_weather_fill.json")
    era5 = read_json("data/physical_hazard/physical_hazard_003_ERA5-Land_hourly_aggregate_stats.json")
    gpm = read_json("data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json")
    chirps = read_json("data/physical_hazard/physical_hazard_005_CHIRPS_daily_event_accumulated_precipitation.json")

    event_day = date.fromisoformat(anchor["temporal_window"]["start_date"])
    prior14_start = event_day - timedelta(days=14)
    prior7_start = event_day - timedelta(days=7)
    prior_end = event_day - timedelta(days=1)

    openmeteo_metrics = window_metrics(openmeteo_series(openmeteo), event_day)
    power_metrics = window_metrics(power_series(power), event_day)
    grid_means = {
        "era5_land": round2(era5["stats"]["precipitation_sum_mm_mean"]),
        "gpm": round2(gpm["stats"]["gpm_event_precip_mm_mean"]),
        "chirps": round2(chirps["stats"]["chirps_event_precip_mm_mean"]),
    }
    grid_le5_count = sum(1 for value in grid_means.values() if value <= 5.0)

    openmeteo_gate = (
        openmeteo_metrics["prior14_mm"] >= 100.0
        and openmeteo_metrics["event_day_mm"] <= 5.0
        and openmeteo_metrics["ratio_prior14_to_event"] >= 20.0
    )
    power_gate = (
        power_metrics["prior14_mm"] >= 300.0
        and power_metrics["event_day_mm"] <= 10.0
        and power_metrics["ratio_prior14_to_event"] >= 20.0
    )
    grid_consensus_gate = grid_le5_count >= 2
    answer = (
        "antecedent_wetness_ledger_pass"
        if openmeteo_gate and power_gate and grid_consensus_gate
        else "antecedent_wetness_ledger_fail"
    )

    primary_gt = {
        "answer": answer,
        "target_family": TARGET_FAMILY,
        "window": {
            "prior14": f"{prior14_start.isoformat()}..{prior_end.isoformat()}",
            "prior7": f"{prior7_start.isoformat()}..{prior_end.isoformat()}",
            "event_day": event_day.isoformat(),
        },
        "daily_metrics": {
            "openmeteo": openmeteo_metrics,
            "power": power_metrics,
        },
        "grid_means_mm": {
            **grid_means,
            "le5_count": grid_le5_count,
        },
        "gates": {
            "openmeteo_gate": openmeteo_gate,
            "power_gate": power_gate,
            "grid_consensus_gate": grid_consensus_gate,
        },
        "formula_note": "ratio=prior14/event_day; answer passes only if all three gates pass",
    }

    output = {
        "schema_version": "1.0",
        "task_version": "v3.2_numeric",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "target_family": TARGET_FAMILY,
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "package_relative_path": PACKAGE_RELATIVE_PATH,
        "primary_gt": primary_gt,
        "event": {
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_date": event_day.isoformat(),
            "location": anchor["spatial_window"]["location_text"],
        },
        "key_values": {
            "thresholds": {
                "openmeteo_prior14_min_mm": 100.0,
                "openmeteo_event_day_max_mm": 5.0,
                "power_prior14_min_mm": 300.0,
                "power_event_day_max_mm": 10.0,
                "ratio_min": 20.0,
                "grid_le5_count_min": 2,
            },
            "raw_grid_event_day_means_mm": {
                "era5_land": era5["stats"]["precipitation_sum_mm_mean"],
                "gpm": gpm["stats"]["gpm_event_precip_mm_mean"],
                "chirps": chirps["stats"]["chirps_event_precip_mm_mean"],
            },
        },
        "numeric_tolerances": {
            "daily_precip_mm": 0.1,
            "ratio_prior14_to_event": 0.1,
            "grid_mean_mm": 0.01,
            "le5_count": 0,
        },
        "decision_rule": {
            "summary": "Compute prior-window precipitation, event-day precipitation, prior14/event-day ratios, and a three-source low-event-day consensus count.",
            "answer_rule": "antecedent_wetness_ledger_pass requires openmeteo_gate, power_gate, and grid_consensus_gate to all be true.",
        },
        "rubric": RUBRIC,
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
    }
    (TASK_DIR / "computed_gt.json").write_text(
        json.dumps(output, indent=2, ensure_ascii=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
